def embedded_image_html(b64_data, *, mime="image/png", max_width=None, width=None, alt=""):
    style = "display:block;height:auto;margin-left:auto;margin-right:auto;"
    if width is not None:
        style += f"width:{width}px;max-width:100%;"
    elif max_width is not None:
        style += f"width:100%;max-width:{max_width}px;"
    else:
        style += "width:100%;"
    return f'<img src="data:{mime};base64,{b64_data}" alt="{alt}" style="{style}">'


