def persistent_number(label, key, *, min_value, max_value=None, step=1, fmt=None):
    temp = prepare_temp(key)
    kwargs = {
        "label": label,
        "min_value": min_value,
        "step": step,
        "key": temp,
        "on_change": sync_temp,
        "args": (key,),
    }
    if max_value is not None:
        kwargs["max_value"] = max_value
    if fmt is not None:
        kwargs["format"] = fmt
    return st.number_input(**kwargs)


def persistent_slider(label, key, min_value, max_value):
    temp = prepare_temp(key)
    return st.slider(
        label,
        min_value,
        max_value,
        key=temp,
        on_change=sync_temp,
        args=(key,),
    )


def persistent_checkbox(label, key):
    temp = prepare_temp(key)
    return st.checkbox(
        label,
        key=temp,
        on_change=sync_temp,
        args=(key,),
    )


def persistent_selectbox(label, key, options):
    temp = prepare_temp(key)
    current = st.session_state[key]
    if current not in options:
        st.session_state[key] = options[0]
        st.session_state[temp] = options[0]
    return st.selectbox(
        label,
        options,
        key=temp,
        on_change=sync_temp,
        args=(key,),
    )


