def api_secret():
    return st.secrets["APB_SECRET"]


try:
    ACCESS_CODE = st.secrets["ACCESS_CODE"]
except Exception:
    ACCESS_CODE = "ALPHA2026"


def valid_skool_username(value):
    """Skool-navnet er brugerens primære reference. Hold valideringen bevidst mild."""
    value = str(value or "").strip()
    return 2 <= len(value) <= 80


def legacy_server_email_for_skool(skool_username):
    """Bagudkompatibilitet med SIMGROVA-endpointets gamle email-validering.

    Brugeren ser eller anvender ikke denne adresse. Den er en deterministisk,
    ikke-leverbar placeholder på example.com, så den gamle server kan acceptere
    ordren, indtil endpointet senere ændres til Skool username.
    """
    raw = str(skool_username or "").strip().casefold()
    digest = hashlib.sha256(raw.encode("utf-8")).hexdigest()[:16]
    return f"apb-{digest}@example.com"


def generate_result_user_id():
    """Opret et kort, ikke-gætteligt ID til det kommende APB-resultatprogram."""
    return "APB-" + secrets.token_hex(4).upper()


def generate_result_access_code():
    """Opret en læsevenlig adgangskode uden let forvekslelige tegn."""
    alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"
    return "".join(secrets.choice(alphabet) for _ in range(10))


def ensure_result_credentials():
    """Opret kun legitimationsoplysninger én gang pr. aktiv request-session."""
    if not str(st.session_state.result_user_id or "").strip():
        st.session_state.result_user_id = generate_result_user_id()
    if not str(st.session_state.result_access_code or "").strip():
        st.session_state.result_access_code = generate_result_access_code()


def show_login():
    cover_left, cover_middle, cover_right = st.columns([1.5, 4, 1.5])
    with cover_middle:
        st.markdown(
            embedded_image_html(COVER_IMAGE_B64, mime="image/webp", max_width=694, alt="Alpha Portfolio Builder"),
            unsafe_allow_html=True,
        )

    st.markdown(
        "<h2 style='text-align:center;margin-top:0.2rem;'>Access Alpha Portfolio Builder</h2>",
        unsafe_allow_html=True,
    )
    st.markdown(
        "<p style='text-align:center;color:#6b7280;'>"
        "Enter your name (optional), Skool username and access code to continue.</p>",
        unsafe_allow_html=True,
    )

    c1, c2, c3 = st.columns([1, 1.2, 1])
    with c2:
        with st.form("login_form"):
            name = st.text_input("Name (optional)")
            skool_username = st.text_input("Skool username")
            code = st.text_input("Access code", type="password")
            submitted = st.form_submit_button(
                "CONTINUE",
                type="primary",
                use_container_width=True,
            )

        if submitted:
            clean_skool_username = skool_username.strip()
            if not valid_skool_username(clean_skool_username):
                st.error("Please enter your Skool username.")
            elif code != ACCESS_CODE:
                st.error("Incorrect access code.")
            else:
                st.session_state.logged_in = True
                st.session_state.user_name = name.strip()
                st.session_state.skool_username = clean_skool_username
                st.rerun()


if not st.session_state.logged_in:
    show_login()
    st.stop()


