with logout_col:
    if st.button("Log out", use_container_width=True):
        st.session_state.logged_in = False
        st.session_state.skool_username = ""
        st.session_state.user_name = ""
        st.session_state.result_user_id = ""
        st.session_state.result_access_code = ""
        st.session_state.confirmation_saved = False
        st.session_state.wizard_step = 0
        st.rerun()


step = int(st.session_state.wizard_step)
step_name = STEPS[step]

st.markdown(f"**Step {step + 1} of {len(STEPS)} · {step_name}**")
st.progress((step + 1) / len(STEPS))

# Fast navigation stays in the same position on every step.
# On Review & Build the final BUILD button remains in the review section itself.
if not (step == len(STEPS) - 1 and st.session_state.build_submitted):
    nav_left, nav_middle, nav_right = st.columns([1, 4, 1])

    with nav_left:
        if step > 0 and st.button(
            "← Back",
            use_container_width=True,
            key="nav_back_top",
        ):
            st.session_state.wizard_step = max(0, step - 1)
            st.rerun()

